<#
    win-toolbox - All-in-one menu
    Version 1.0.0 | Generated by build.ps1 - do not edit, edit src/ instead.
    Source: https://github.com/Bladeage/win-toolbox
    Run:    irm https://raw.githubusercontent.com/Bladeage/win-toolbox/main/dist/win-toolbox.ps1 | iex
#>
param([string]$Tool)
& {
$SelfUrl = 'https://raw.githubusercontent.com/Bladeage/win-toolbox/main/dist/win-toolbox.ps1'
$ToolboxVersion = '1.0.0'

# ---------------------------------------------------------------------------
# common.ps1 - shared helpers for every win-toolbox script.
# Must stay Windows PowerShell 5.1 compatible (no ternary, no ??, no classes).
# ---------------------------------------------------------------------------

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'   # Invoke-WebRequest is much faster without the progress bar
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

# Upstream URLs of third-party scripts/binaries - the single place to change them.
$Urls = @{
    AdwCleaner     = 'https://adwcleaner.malwarebytes.com/adwcleaner?channel=release'
    WinGetInstall  = 'https://asheroto.com/winget'          # asheroto/winget-install
    MAS            = 'https://get.activated.win'            # Microsoft Activation Scripts (massgrave)
    OfficeToolPlus = 'https://officetool.plus'              # serves a .ps1 to PowerShell user agents
    WinUtil        = 'https://christitus.com/win'           # Chris Titus Tech WinUtil
    WinScript      = 'https://winscript.cc/irm'             # flick9000/winscript
}

# ---- output ---------------------------------------------------------------

function Write-Title {
    param([string]$Text)
    Write-Host ''
    Write-Host "== $Text ==" -ForegroundColor Cyan
}
function Write-Step { param([string]$Text) Write-Host "-> $Text" -ForegroundColor White }
function Write-Ok   { param([string]$Text) Write-Host "   $Text" -ForegroundColor Green }
function Write-Warn { param([string]$Text) Write-Host "   $Text" -ForegroundColor Yellow }
function Write-Fail { param([string]$Text) Write-Host "   $Text" -ForegroundColor Red }

function Wait-AnyKey {
    param([string]$Prompt = 'Press any key to continue...')
    Write-Host ''
    Write-Host $Prompt -ForegroundColor DarkGray
    try { $null = [Console]::ReadKey($true) } catch { $null = Read-Host }
}

function Confirm-Action {
    param([Parameter(Mandatory)][string]$Question)
    $answer = Read-Host "$Question [y/N]"
    return ($answer -match '^(y|yes)$')
}

# ---- environment ----------------------------------------------------------

function Test-Command {
    param([Parameter(Mandatory)][string]$Name)
    return [bool](Get-Command $Name -ErrorAction SilentlyContinue)
}

function Test-IsAdmin {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    return ([Security.Principal.WindowsPrincipal]$identity).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Invoke-Elevated {
    <#
    .SYNOPSIS
        Re-launches the current entry point with administrator rights.
    .DESCRIPTION
        Works for both execution styles: from a file (re-runs the file) and from
        `irm <url> | iex` (re-runs the irm|iex one-liner using $SelfUrl).
        Returns $true when a new elevated process was started - the caller should
        `return` in that case. Returns $false when already elevated.
    #>
    param(
        [Parameter(Mandatory)][string]$SelfUrl,
        [string]$Arguments = ''
    )
    if (Test-IsAdmin) { return $false }

    Write-Warn 'Administrator rights are required - requesting elevation (UAC prompt)...'
    $hostExe = (Get-Process -Id $PID).Path
    if (-not $hostExe) { $hostExe = 'powershell.exe' }

    if ($PSCommandPath) {
        $command = "& '$PSCommandPath' $Arguments"
    } else {
        $command = "irm '$SelfUrl' | iex"
    }
    Start-Process -FilePath $hostExe -Verb RunAs -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', $command)
    return $true
}

function Update-SessionPath {
    # Pick up PATH changes made by installers (e.g. winget) without opening a new shell.
    $machine = [Environment]::GetEnvironmentVariable('Path', 'Machine')
    $user = [Environment]::GetEnvironmentVariable('Path', 'User')
    $env:Path = "$machine;$user"
}

# ---- network --------------------------------------------------------------

function Get-RemoteFile {
    param(
        [Parameter(Mandatory)][string]$Uri,
        [Parameter(Mandatory)][string]$OutFile,
        [int]$Retries = 3
    )
    for ($attempt = 1; $attempt -le $Retries; $attempt++) {
        try {
            Invoke-WebRequest -Uri $Uri -OutFile $OutFile -UseBasicParsing
            if ((Get-Item $OutFile).Length -gt 0) { return }
            throw 'downloaded file is empty'
        } catch {
            if ($attempt -ge $Retries) { throw "Download failed after $Retries attempts: $Uri ($_)" }
            Write-Warn "Download attempt $attempt failed ($_), retrying..."
            Start-Sleep -Seconds (2 * $attempt)
        }
    }
}

function Invoke-RemoteScript {
    <# Fetches a remote PowerShell script and runs it in the current session (irm | iex). #>
    param(
        [Parameter(Mandatory)][string]$Url,
        [string]$Name = $Url
    )
    Write-Step "Fetching $Name from $Url ..."
    $code = Invoke-RestMethod -Uri $Url -UseBasicParsing
    Invoke-Expression $code
}

# ---- winget ---------------------------------------------------------------

function Install-WinGet {
    <# Installs or repairs WinGet via asheroto's winget-install script. #>
    param([switch]$Force)
    Write-Title 'WinGet'
    if ((Test-Command winget) -and -not $Force) {
        Write-Ok "WinGet is already installed ($(& winget --version))."
        return
    }
    Invoke-RemoteScript -Url $Urls.WinGetInstall -Name 'winget-install (asheroto)'
    Update-SessionPath
    if (-not (Test-Command winget)) {
        throw 'WinGet is still not available in this session. Open a new terminal and try again.'
    }
    Write-Ok "WinGet ready ($(& winget --version))."
}

function Install-WinGetPackage {
    <#
    .SYNOPSIS
        Installs one package by exact ID, silently. Returns $true on success / already installed.
    .PARAMETER Force
        Pass --force to winget: (re)install even when the package is already present.
    .PARAMETER Source
        Restrict to a winget source, e.g. 'msstore'.
    #>
    param(
        [Parameter(Mandatory)][string]$Id,
        [string]$Label = $Id,
        [string]$Source,
        [switch]$Force
    )
    Write-Host ("   {0,-45} " -f $Label) -NoNewline
    $wingetArgs = @(
        'install', '--exact', '--id', $Id,
        '--accept-package-agreements', '--accept-source-agreements',
        '--silent', '--disable-interactivity'
    )
    if ($Source) { $wingetArgs += @('--source', $Source) }
    if ($Force) { $wingetArgs += '--force' }
    $null = & winget @wingetArgs 2>&1
    $code = $LASTEXITCODE
    switch ($code) {
        0            { Write-Host 'installed' -ForegroundColor Green; return $true }
        -1978335189  { Write-Host 'already installed' -ForegroundColor DarkGreen; return $true }   # 0x8A15002B UPDATE_NOT_APPLICABLE
        -1978335135  { Write-Host 'already installed' -ForegroundColor DarkGreen; return $true }   # 0x8A150061 PACKAGE_ALREADY_INSTALLED
        -1978335212  { Write-Host 'not found in winget' -ForegroundColor Yellow; return $false }   # 0x8A150014 NO_APPLICATIONS_FOUND
        default      { Write-Host ("failed (0x{0:X8})" -f $code) -ForegroundColor Red; return $false }
    }
}

# ---------------------------------------------------------------------------
# tools/adwcleaner.ps1 - download, run and remove Malwarebytes AdwCleaner.
# ---------------------------------------------------------------------------

function Invoke-AdwCleaner {
    <#
    .SYNOPSIS
        Downloads AdwCleaner to %TEMP%, runs it interactively and deletes it afterwards.
    .NOTES
        AdwCleaner asks for elevation itself, so this tool does not need an admin shell.
    #>
    Write-Title 'Malwarebytes AdwCleaner'
    $exe = Join-Path ([IO.Path]::GetTempPath()) 'adwcleaner.exe'
    try {
        Write-Step 'Downloading the latest AdwCleaner...'
        Get-RemoteFile -Uri $Urls.AdwCleaner -OutFile $exe
        Write-Ok "Saved to $exe"

        Write-Step 'Starting AdwCleaner - close it when you are done.'
        Start-Process -FilePath $exe -Wait
        Write-Ok 'AdwCleaner finished.'
    } finally {
        if (Test-Path $exe) {
            Remove-Item $exe -Force -ErrorAction SilentlyContinue
            Write-Ok 'Temporary file removed.'
        }
    }
}

# ---------------------------------------------------------------------------
# tools/windows-update.ps1 - install all pending Windows updates via PSWindowsUpdate.
# ---------------------------------------------------------------------------

function Invoke-WindowsUpdate {
    <#
    .SYNOPSIS
        Installs the PSWindowsUpdate module if needed, then installs every available update.
    .PARAMETER NoReboot
        Do not reboot automatically when an update requires it.
    .NOTES
        Requires an elevated shell.
    #>
    param([switch]$NoReboot)

    Write-Title 'Windows Update (PSWindowsUpdate)'
    if (-not (Test-IsAdmin)) { throw 'Administrator rights are required for Windows Update.' }

    Write-Step 'Checking NuGet package provider...'
    if (Get-PackageProvider -Name NuGet -ListAvailable -ErrorAction SilentlyContinue) {
        Write-Ok 'NuGet provider present.'
    } else {
        Write-Step 'Installing NuGet package provider...'
        $null = Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force
    }

    Write-Step 'Checking PSWindowsUpdate module...'
    if (Get-Module -ListAvailable -Name PSWindowsUpdate) {
        Write-Ok 'PSWindowsUpdate present.'
    } else {
        Write-Step 'Installing PSWindowsUpdate from the PowerShell Gallery...'
        Install-Module -Name PSWindowsUpdate -Force
    }
    Import-Module PSWindowsUpdate

    Write-Step 'Searching for updates...'
    $updates = @(Get-WindowsUpdate)
    if ($updates.Count -eq 0) {
        Write-Ok 'No updates available - system is up to date.'
        return
    }
    $updates | Format-Table -AutoSize KB, Size, Title | Out-String | Write-Host

    Write-Step "Installing $($updates.Count) update(s)..."
    if ($NoReboot) {
        Get-WindowsUpdate -Install -AcceptAll -IgnoreReboot
    } else {
        Write-Warn 'The system will reboot automatically if an update requires it.'
        Get-WindowsUpdate -Install -AcceptAll -AutoReboot
    }
    Write-Ok 'Windows Update finished.'
}

# ---------------------------------------------------------------------------
# tools/redists.ps1 - PC gaming redistributables + common tools via winget.
# Successor of the PC-Gaming-Redists AIOInstaller.bat (harryeffinpotter/skrimix),
# rewritten in PowerShell with an explicit package list instead of `winget search` scraping.
# ---------------------------------------------------------------------------

$RedistPackages = @(
    # --- Visual C++ runtimes (x86 + x64, every generation still used by games) ---
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2005.x86' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2005.x64' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2008.x86' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2008.x64' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2010.x86' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2010.x64' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2012.x86' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2012.x64' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2013.x86' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2013.x64' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2015+.x86' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCRedist.2015+.x64' },
    @{ Group = 'Visual C++'; Id = 'Microsoft.VCLibs.Desktop.14' },        # VCLibs for Store / Game Pass apps
    # --- .NET desktop runtimes ---
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.3_1' },
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.5' },
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.6' },
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.7' },
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.8' },
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.9' },
    @{ Group = '.NET'; Id = 'Microsoft.DotNet.DesktopRuntime.10' },
    # --- DirectX / XNA ---
    @{ Group = 'DirectX & XNA'; Id = 'Microsoft.DirectX' },
    @{ Group = 'DirectX & XNA'; Id = 'Microsoft.XNARedist' },
    # --- common tools ---
    @{ Group = 'Tools'; Id = '7zip.7zip' },
    @{ Group = 'Tools'; Id = 'Microsoft.PowerShell' },
    @{ Group = 'Tools'; Id = 'Microsoft.WindowsTerminal' },
    @{ Group = 'Java'; Id = 'Oracle.JavaRuntimeEnvironment' },
    @{ Group = 'Java'; Id = 'Oracle.JDK.22' }
)

function Install-GamingRedists {
    <#
    .SYNOPSIS
        Installs all Visual C++ / .NET runtimes, DirectX, XNA and a few common tools via winget.
    .PARAMETER Group
        Only install packages of the given group(s), e.g. -Group 'Visual C++','.NET'.
    .PARAMETER Force
        Reinstall packages that are already present (winget --force) - the old
        "scorched earth" behaviour of the batch installer.
    .NOTES
        Requires an elevated shell. Installs WinGet first if it is missing.
    #>
    param(
        [string[]]$Group,
        [switch]$Force
    )

    Write-Title 'PC Gaming Redistributables'
    if (-not (Test-IsAdmin)) { throw 'Administrator rights are required to install redistributables.' }

    Install-WinGet

    $packages = $RedistPackages
    if ($Group) { $packages = $packages | Where-Object { $Group -contains $_.Group } }

    $failed = @()
    foreach ($grp in ($packages | ForEach-Object { $_.Group } | Select-Object -Unique)) {
        Write-Step "$grp"
        foreach ($pkg in ($packages | Where-Object { $_.Group -eq $grp })) {
            if (-not (Install-WinGetPackage -Id $pkg.Id -Force:$Force)) { $failed += $pkg.Id }
        }
    }

    if (-not $Group -or $Group -contains '.NET') {
        Write-Step '.NET Framework 3.5 (Windows feature, needed by older games)'
        try {
            $feature = Get-WindowsOptionalFeature -Online -FeatureName NetFx3
            if ($feature.State -eq 'Enabled') {
                Write-Ok 'already enabled'
            } else {
                $null = Enable-WindowsOptionalFeature -Online -FeatureName NetFx3 -All -NoRestart
                Write-Ok 'enabled'
            }
        } catch {
            Write-Warn "could not enable NetFx3: $_"
            $failed += 'NetFx3'
        }
    }

    Write-Host ''
    if ($failed.Count -eq 0) {
        Write-Ok 'All packages installed.'
    } else {
        Write-Warn "$($failed.Count) package(s) failed: $($failed -join ', ')"
    }
}

# ---------------------------------------------------------------------------
# tools/external.ps1 - thin wrappers around well-known third-party irm|iex scripts.
# Each one runs code from the internet - the URL is shown before it runs.
# ---------------------------------------------------------------------------

function Invoke-MAS {
    <# Microsoft Activation Scripts (massgrave.dev) - Windows / Office activation. #>
    Write-Title 'Microsoft Activation Scripts (MAS)'
    Invoke-RemoteScript -Url $Urls.MAS -Name 'MAS'
}

function Invoke-OfficeToolPlus {
    <# Office Tool Plus - download/deploy/manage Microsoft Office. #>
    Write-Title 'Office Tool Plus'
    Invoke-RemoteScript -Url $Urls.OfficeToolPlus -Name 'Office Tool Plus'
}

function Invoke-WinUtil {
    <# Chris Titus Tech's Windows Utility - tweaks, debloat, installs. #>
    Write-Title 'WinUtil (Chris Titus Tech)'
    Invoke-RemoteScript -Url $Urls.WinUtil -Name 'WinUtil'
}

function Install-HardenSystemSecurity {
    <#
    .SYNOPSIS
        Installs HotCakeX's "Harden System Security" app (Microsoft Store) and starts it.
    .NOTES
        Successor of the deprecated Harden-Windows-Security-Module. Needs Windows 11 22H2+
        and an elevated shell.
    #>
    Write-Title 'Harden System Security (HotCakeX)'
    $build = [Environment]::OSVersion.Version.Build
    if ($build -lt 22621) {
        throw "Harden System Security needs Windows 11 22H2 or newer (this is build $build)."
    }
    if (-not (Test-IsAdmin)) { throw 'Administrator rights are required.' }
    Install-WinGet
    Write-Step 'Installing from the Microsoft Store via winget...'
    if (Install-WinGetPackage -Id '9p7ggfl7dx57' -Label 'Harden System Security' -Source msstore) {
        Write-Step 'Starting Harden System Security...'
        Start-Process 'shell:AppsFolder\$((Get-StartApps | Where-Object Name -eq "Harden System Security" | Select-Object -First 1).AppID)' -ErrorAction SilentlyContinue
        Write-Ok 'Done. If the app did not open, find "Harden System Security" in the Start menu.'
    }
}

function Invoke-WinScript {
    <# flick9000/winscript - debloat, privacy, performance, app installer. #>
    Write-Title 'WinScript (flick9000)'
    Invoke-RemoteScript -Url $Urls.WinScript -Name 'WinScript'
}

# ---------------------------------------------------------------------------
# menu.ps1 - the all-in-one text menu (with optional Out-GridView mode).
# ---------------------------------------------------------------------------

$MenuItems = @(
    @{ Key = '1'; Id = 'activate';   Name = 'Activate Windows / Office';  Description = 'Microsoft Activation Scripts (massgrave.dev)'; Action = { Invoke-MAS } },
    @{ Key = '2'; Id = 'update';     Name = 'Windows Update';             Description = 'Install all pending updates (PSWindowsUpdate)';  Action = { Invoke-WindowsUpdate } },
    @{ Key = '3'; Id = 'winget';     Name = 'Install / repair WinGet';    Description = 'winget-install by asheroto';                     Action = { Install-WinGet -Force } },
    @{ Key = '4'; Id = 'redists';    Name = 'Gaming redistributables';    Description = 'VC++, .NET, DirectX, XNA, 7zip, PowerShell, Terminal, Java'; Action = { Install-GamingRedists } },
    @{ Key = '5'; Id = 'office';     Name = 'Office Tool Plus';           Description = 'Download / deploy Microsoft Office';            Action = { Invoke-OfficeToolPlus } },
    @{ Key = '6'; Id = 'winutil';    Name = 'WinUtil';                    Description = "Chris Titus Tech's Windows utility";            Action = { Invoke-WinUtil } },
    @{ Key = '7'; Id = 'winscript';  Name = 'WinScript';                  Description = 'flick9000/winscript - debloat & privacy';        Action = { Invoke-WinScript } },
    @{ Key = '8'; Id = 'adwcleaner'; Name = 'AdwCleaner';                 Description = 'Malwarebytes adware cleaner';                    Action = { Invoke-AdwCleaner } },
    @{ Key = '9'; Id = 'harden';     Name = 'Harden System Security';     Description = 'HotCakeX hardening app (Win 11 22H2+, MS Store)';  Action = { Install-HardenSystemSecurity } }
)

function Show-Banner {
    try { $Host.UI.RawUI.WindowTitle = "win-toolbox v$ToolboxVersion" } catch { Write-Verbose "cannot set window title: $_" }
    Clear-Host
    Write-Host ''
    Write-Host '  win-toolbox' -ForegroundColor Cyan -NoNewline
    Write-Host "  v$ToolboxVersion" -ForegroundColor DarkGray
    Write-Host '  https://github.com/Bladeage/win-toolbox' -ForegroundColor DarkGray
    Write-Host ''
}

function Show-TextMenu {
    Show-Banner
    foreach ($item in $MenuItems) {
        Write-Host ("  [{0}] " -f $item.Key) -ForegroundColor Yellow -NoNewline
        Write-Host ("{0,-28}" -f $item.Name) -NoNewline
        Write-Host $item.Description -ForegroundColor DarkGray
    }
    Write-Host ''
    Write-Host '  [G] Grid view    [Q] Quit' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  Select: ' -NoNewline
    return Read-MenuKey
}

function Read-MenuKey {
    # Returns the pressed key as a one-character string ('Q' for Escape). Replaced by tests/smoke.ps1.
    $key = [Console]::ReadKey($true)
    if ($key.Key -eq 'Escape') { return 'Q' }
    return [string]$key.KeyChar
}

function Show-GridMenu {
    # Returns the selected key, or $null when cancelled / unavailable.
    if (-not (Get-Command Out-GridView -ErrorAction SilentlyContinue)) {
        Write-Warn 'Out-GridView is not available in this PowerShell - falling back to the text menu.'
        Start-Sleep -Seconds 2
        return $null
    }
    $rows = $MenuItems | ForEach-Object {
        [pscustomobject]@{ Key = $_.Key; Tool = $_.Name; Description = $_.Description }
    }
    $selection = $rows | Out-GridView -Title "win-toolbox v$ToolboxVersion - pick a tool" -OutputMode Single
    if ($selection) { return $selection.Key }
    return $null
}

function Invoke-MenuItem {
    param([Parameter(Mandatory)][string]$Selector)
    $item = $MenuItems | Where-Object { $_.Key -eq $Selector -or $_.Id -eq $Selector } | Select-Object -First 1
    if (-not $item) {
        Write-Warn "Unknown selection '$Selector'."
        Start-Sleep -Seconds 1
        return
    }
    Clear-Host
    try {
        & $item.Action
    } catch {
        Write-Fail "$($item.Name) failed: $_"
    }
    Wait-AnyKey 'Press any key to return to the menu...'
}

function Show-Menu {
    <#
    .SYNOPSIS
        Runs the interactive menu, or a single tool when -Tool is given (e.g. -Tool update).
    #>
    param([string]$Tool)

    if ($Tool) {
        Invoke-MenuItem -Selector $Tool
        return
    }

    $mode = 'text'
    while ($true) {
        if ($mode -eq 'grid') {
            $key = Show-GridMenu
            if ($null -eq $key) { $mode = 'text'; continue }
        } else {
            $key = Show-TextMenu
        }
        switch -Regex ($key) {
            '^[qQ]$' { Write-Host ''; return }
            '^[gG]$' { $mode = 'grid'; break }
            default  { Invoke-MenuItem -Selector $key }
        }
    }
}

# ---- entry ----------------------------------------------------------------
$elevArgs = if ($Tool) { "-Tool $Tool" } else { "" }
if (Invoke-Elevated -SelfUrl $SelfUrl -Arguments $elevArgs) { return }
try {
    Show-Menu -Tool $Tool
} catch {
    Write-Fail "Error: $_"
}

}